#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL files from the migrations directory, sorted by name
 * @returns {string[]} Array of filenames
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`⚠️  Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
      console.warn(`⚠️  No SQL files found in ${MIGRATIONS_DIR}`);
      return [];
    }

    // Sort files by name (typically by timestamp or version number)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Apply migrations by logging each filename in order
 */
function applyMigrations() {
  console.log('🚀 Starting database migrations...\n');

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('✅ No migrations to apply.');
    return;
  }

  console.log(`📁 Found ${migrations.length} migration(s):\n`);

  migrations.forEach((filename, index) => {
    const filepath = path.join(MIGRATIONS_DIR, filename);

    try {
      // Read the file to validate it exists and is readable
      const content = fs.readFileSync(filepath, 'utf8');
      const lineCount = content.split('\n').length;

      console.log(`   ${index + 1}. ${filename} (${lineCount} lines)`);

      // Log: would execute this migration
      console.log(`      → Would apply migration: ${filepath}`);
    } catch (error) {
      console.error(`   ❌ Error reading ${filename}: ${error.message}`);
      process.exit(1);
    }
  });

  console.log(`\n✅ Migration preview complete. Ready to apply ${migrations.length} migration(s).`);
}

/**
 * Main execution
 */
if (require.main === module) {
  applyMigrations();
}

module.exports = { getMigrationFiles, applyMigrations };

-- Add comments table
CREATE TABLE comments (
  id INT PRIMARY KEY AUTO_INCREMENT,
  post_id INT NOT NULL,
  user_id INT NOT NULL,
  content TEXT NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX idx_post_id ON comments(post_id);
CREATE INDEX idx_user_id ON comments(user_id);

