 * Runs on http://localhost:3003
 * Receives migration audit logs and simulates compliance logging
 */

const http = require('http');

const PORT = 3003;

const server = http.createServer((req, res) => {
  // Handle CORS and content-type
  res.setHeader('Content-Type', 'application/json');

  if (req.method === 'POST' && req.path === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);

        console.log('\n📨 Received Audit Log:');
        console.log('─'.repeat(50));
        console.log(`Timestamp: ${auditData.timestamp}`);
        console.log(`Service: ${auditData.service}`);
        console.log(`Action: ${auditData.action}`);
        console.log(`Migrations Count: ${auditData.migrationsCount}`);
        console.log('Environment Variables:');
        Object.entries(auditData.environment).forEach(([key, value]) => {
          // Mask sensitive values for console output
          const displayValue = key.toLowerCase().includes('password') || 
                             key.toLowerCase().includes('secret') ||
                             key.toLowerCase().includes('url')
            ? '***'
            : value;
          console.log(`  ${key}: ${displayValue}`);
        });
        console.log('─'.repeat(50));

        // Generate audit ID
        const auditId = `AUDIT-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;

        res.statusCode = 200;
        res.end(JSON.stringify({
          success: true,
          message: 'Audit logged successfully',
          auditId: auditId,
          receivedAt: new Date().toISOString()
        }));
      } catch (error) {
        res.statusCode = 400;
        res.end(JSON.stringify({
          success: false,
          message: 'Invalid JSON in request',
          error: error.message
        }));
      }
    });
  } else if (req.method === 'GET' && req.path === '/health') {
    res.statusCode = 200;
    res.end(JSON.stringify({
      status: 'ok',
      service: 'audit-service',
      timestamp: new Date().toISOString()
    }));
  } else {
    res.statusCode = 404;
    res.end(JSON.stringify({
      success: false,
      message: 'Endpoint not found'
    }));
  }
});

server.on('clientError', (err, socket) => {
  console.error('Client error:', err);
  socket.end('HTTP/1.1 400 Bad Request\r\n\r\n');
});

server.listen(PORT, () => {
  console.log(`\n🔒 Audit Service running on http://localhost:${PORT}`);
  console.log(`📝 Endpoint: POST /api/audit`);
  console.log(`❤️  Health check: GET /health`);
  console.log('\nWaiting for audit logs...\n');
});

