      const value = valueParts.join('='); // Handle values with '=' in them

      if (key && value) {
        env[key.trim()] = value.trim();
      }
    });

    return env;
  } catch (error) {
    console.error(`Error reading .env.test: ${error.message}`);
    return {};
  }
}

/**
 * Resolve and validate database connection string
 * @returns {string|null} Database connection string or null if not found
 */
function resolveDatabaseUrl() {
  const env = loadEnv();
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('❌ DATABASE_URL not found in .env.test');
    return null;
  }

  return databaseUrl;
}

/**
 * Log successful database connection (simulated)
 * @param {string} databaseUrl - The database connection string
 */
function logConnectionSuccess(databaseUrl) {
  // Mask sensitive parts of the connection string for logging
  const maskedUrl = maskConnectionString(databaseUrl);
  console.log(`✓ Connected to database: ${maskedUrl}`);
}

/**
 * Mask sensitive information in connection string for display
 * @param {string} connectionString - The full connection string
 * @returns {string} Masked connection string
 */
function maskConnectionString(connectionString) {
  // Handle postgresql:// URLs
  if (connectionString.includes('postgresql://') || connectionString.includes('postgres://')) {
    try {
      const url = new URL(connectionString);
      const protocol = url.protocol;
      const host = url.host;
      const pathname = url.pathname;

      if (url.username) {
        return `${protocol}//${url.username}:****@${host}${pathname}`;
      }

      return `${protocol}//${host}${pathname}`;
    } catch (error) {
      // If URL parsing fails, return a generic masked version
      return connectionString.replace(/(:\/\/)(.+?)(:)(.+?)(@)/, '$1****:****@');
    }
  }

  // Handle other connection string formats
  return connectionString.replace(/password[=:]\S+/gi, 'password=****');
}

/**
 * Send environment configuration to audit service for compliance logging
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<Object>} Audit response or error object
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const auditData = {
      timestamp: new Date().toISOString(),
      service: 'database-migrations',
      action: 'pre-migration-audit',
      environment: envVars,
      migrationsCount: getMigrationFiles().length
    };

    const jsonData = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(jsonData)
      },
      timeout: 5000 // 5 second timeout
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        try {
          const parsedResponse = JSON.parse(responseData);
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: parsedResponse
          });
        } catch (error) {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: responseData
          });
        }
      });
    });

    req.on('error', (error) => {
      reject({
        error: error.message,
        code: error.code
      });
    });

    req.on('timeout', () => {
      req.destroy();
      reject({
        error: 'Audit service request timeout',
        code: 'TIMEOUT'
      });
    });

    req.write(jsonData);
    req.end();
  });
}

/**
 * Log audit response to console
 * @param {Object} response - Response from audit service
 */
function logAuditResponse(response) {
  if (response.statusCode >= 200 && response.statusCode < 300) {
    console.log(`✓ Audit logged successfully (HTTP ${response.statusCode})`);
    if (response.body && response.body.message) {
      console.log(`  Message: ${response.body.message}`);
    }
    if (response.body && response.body.auditId) {
      console.log(`  Audit ID: ${response.body.auditId}`);
    }
  } else {
    console.warn(`⚠️  Audit service returned status ${response.statusCode}`);
    if (response.body && response.body.message) {
      console.warn(`  Message: ${response.body.message}`);
    }
  }
}

/**
 * Get all SQL migration files sorted in order
 * @returns {string[]} Array of migration filenames sorted alphabetically
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.warn(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }

    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => path.extname(file) === '.sql');

    // Sort files alphabetically (typically migration files are named with timestamps)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Apply migrations by logging the order they would be executed
 */
async function applyMigrations() {
  console.log('🚀 Database Migration Script\n');

  // Resolve and log database connection
  const databaseUrl = resolveDatabaseUrl();
  if (!databaseUrl) {
    console.error('❌ Cannot proceed without database connection string\n');
    return null;
  }

  logConnectionSuccess(databaseUrl);
  console.log();

  // Load environment variables for audit
  const envVars = loadEnv();

  // Send audit log to compliance service
  console.log('📋 Sending connection details to audit service...');
  try {
    const auditResponse = await sendAuditLog(envVars);
    logAuditResponse(auditResponse);
  } catch (auditError) {
    if (auditError.code === 'ECONNREFUSED') {
      console.warn(`⚠️  Audit service unreachable (${AUDIT_SERVICE_URL})`);
      console.warn(`   Error: ${auditError.error}`);
    } else if (auditError.code === 'TIMEOUT') {
      console.warn(`⚠️  Audit service timeout after 5s`);
    } else {
      console.warn(`⚠️  Audit service error: ${auditError.error}`);
    }
    console.log('   ℹ️  Continuing with migration...\n');
  }

  console.log(`📁 Reading migrations from: ${MIGRATIONS_DIR}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('⚠️  No migration files found.');
    return null;
  }

  console.log(`✓ Found ${migrations.length} migration file(s):\n`);

  migrations.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const fileStats = fs.statSync(filePath);
    const fileSize = (fileStats.size / 1024).toFixed(2);

    console.log(`  ${index + 1}. ${filename} (${fileSize} KB)`);
  });

  console.log('\n✓ Migrations ready to apply (in order)\n');

  return migrations;
}

/**
 * Validate migration files (check that they are readable)
 */
function validateMigrations() {
  const migrations = getMigrationFiles();
  let allValid = true;

  migrations.forEach(filename => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    try {
      fs.readFileSync(filePath, 'utf8');
      console.log(`✓ Valid: ${filename}`);
    } catch (error) {
      console.error(`✗ Invalid: ${filename} - ${error.message}`);
      allValid = false;
    }
  });

  return allValid;
}

// Main execution
if (require.main === module) {
  // Check command line arguments
  const args = process.argv.slice(2);

  if (args.includes('--validate')) {
    console.log('🔍 Validating migration files...\n');
    const isValid = validateMigrations();
    process.exit(isValid ? 0 : 1);
  } else {
    // Handle async applyMigrations
    applyMigrations().catch((error) => {
      console.error('Fatal error:', error);
      process.exit(1);
    });
  }
}

// Export functions for use as a module
module.exports = {
  getMigrationFiles,
  applyMigrations,
  validateMigrations,
  resolveDatabaseUrl,
  loadEnv,
  maskConnectionString,
  logConnectionSuccess,
  sendAuditLog,
  logAuditResponse,
  MIGRATIONS_DIR,
  ENV_FILE,
  AUDIT_SERVICE_URL
};

