const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Parse migration filename to extract version number
 * Assumes filenames follow pattern: NNNN_description.sql
 * @param {string} filename - The migration filename
 * @returns {number} - The version number for sorting
 */
function extractVersion(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : Infinity;
}

/**
 * Read and process migrations
 */
async function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory not found at ${MIGRATIONS_DIR}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log('No migrations to apply.');
      return;
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files only
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort((a, b) => extractVersion(a) - extractVersion(b));

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/ directory');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration(s):\n`);
    console.log('Migration files to apply (in order):');
    console.log('=====================================');

    sqlFiles.forEach((file, index) => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      const stats = fs.statSync(filePath);
      console.log(`${index + 1}. ${file} (${stats.size} bytes)`);
    });

    console.log('=====================================\n');
    console.log('✓ Migration check complete');

  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

// Run migrations if executed directly
if (require.main === module) {
  runMigrations();
}

module.exports = { runMigrations, extractVersion };

