const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Resolves DATABASE_URL from .env.test for connection info
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse migration filename to extract version number
 * Assumes filenames follow pattern: NNNN_description.sql
 * @param {string} filename - The migration filename
 * @returns {number} - The version number for sorting
 */
function extractVersion(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : Infinity;
}

/**
 * Load environment variables from .env.test file
 * @returns {object} - Parsed environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`Environment file not found at ${ENV_FILE}`);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const env = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) {
        return;
      }

      const [key, value] = line.split('=');
      if (key && value) {
        env[key.trim()] = value.trim();
      }
    });

    return env;
  } catch (error) {
    console.error('Error loading environment file:', error.message);
    process.exit(1);
  }
}

/**
 * Parse database URL to extract connection info
 * @param {string} databaseUrl - The DATABASE_URL connection string
 * @returns {object} - Parsed connection info
 */
function parseDatabaseUrl(databaseUrl) {
  try {
    // Handle both postgres:// and postgresql:// schemes
    if (!databaseUrl) {
      throw new Error('DATABASE_URL is not set');
    }

    const url = new URL(databaseUrl);

    return {
      protocol: url.protocol.replace(':', ''),
      username: url.username || 'unknown',
      host: url.hostname || 'localhost',
      port: url.port || (url.protocol === 'postgres:' ? 5432 : 3306),
      database: url.pathname.replace('/', '') || 'unknown',
      fullUrl: databaseUrl
    };
  } catch (error) {
    throw new Error(`Invalid DATABASE_URL format: ${error.message}`);
  }
}

/**
 * Test database connection (simulated)
