  console.log(`Database:  ${connectionInfo.database}`);
  console.log(`User:      ${connectionInfo.username}`);
  console.log('=====================================');
  console.log('✅ Successfully resolved DATABASE_URL from .env.test');
  console.log('✅ Connection verified (simulated)\n');
}

