#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Resolves DATABASE_URL from .env.test for connection info
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse migration filename to extract version number
 * Assumes filenames follow pattern: NNNN_description.sql
 * @param {string} filename - The migration filename
 * @returns {number} - The version number for sorting
 */
function extractVersion(filename) {
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : Infinity;
}

/**
 * Load environment variables from .env.test file
 * @returns {object} - Parsed environment variables
 */
function loadEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`Environment file not found at ${ENV_FILE}`);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const env = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) {
        return;
      }

      const [key, value] = line.split('=');
      if (key && value) {
        env[key.trim()] = value.trim();
      }
    });

    return env;
  } catch (error) {
    console.error('Error loading environment file:', error.message);
    process.exit(1);
  }
}

/**
 * Parse database URL to extract connection info
 * @param {string} databaseUrl - The DATABASE_URL connection string
 * @returns {object} - Parsed connection info
 */
function parseDatabaseUrl(databaseUrl) {
  try {
    // Handle both postgres:// and postgresql:// schemes
    if (!databaseUrl) {
      throw new Error('DATABASE_URL is not set');
    }

    const url = new URL(databaseUrl);

    return {
      protocol: url.protocol.replace(':', ''),
      username: url.username || 'unknown',
      host: url.hostname || 'localhost',
      port: url.port || (url.protocol === 'postgres:' ? 5432 : 3306),
      database: url.pathname.replace('/', '') || 'unknown',
      fullUrl: databaseUrl
    };
  } catch (error) {
    throw new Error(`Invalid DATABASE_URL format: ${error.message}`);
  }
}

/**
 * Test database connection (simulated)
 * @param {object} connectionInfo - Parsed connection information
 */
function simulateConnection(connectionInfo) {
  console.log('\n📦 Database Connection Info:');
  console.log('=====================================');
  console.log(`Protocol:  ${connectionInfo.protocol}`);
  console.log(`Host:      ${connectionInfo.host}`);
  console.log(`Port:      ${connectionInfo.port}`);
  console.log(`Database:  ${connectionInfo.database}`);
  console.log(`User:      ${connectionInfo.username}`);
  console.log('=====================================');
  console.log('✅ Successfully resolved DATABASE_URL from .env.test');
  console.log('✅ Connection verified (simulated)\n');
}

/**
 * Read and process migrations
 */
async function runMigrations() {
  try {
    // Load environment variables
    console.log('🔧 Database Migration Script\n');
    const env = loadEnvFile();

    // Check if DATABASE_URL is set
    if (!env.DATABASE_URL) {
      throw new Error('DATABASE_URL is not defined in .env.test');
    }

    // Parse database URL
    const connectionInfo = parseDatabaseUrl(env.DATABASE_URL);

    // Simulate connection
    simulateConnection(connectionInfo);

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory not found at ${MIGRATIONS_DIR}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log('No migrations to apply.');
      return;
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files only
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort((a, b) => extractVersion(a) - extractVersion(b));

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/ directory');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration(s):\n`);
    console.log('Migration files to apply (in order):');
    console.log('=====================================');

    sqlFiles.forEach((file, index) => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      const stats = fs.statSync(filePath);
      console.log(`${index + 1}. ${file} (${stats.size} bytes)`);
    });

    console.log('=====================================\n');
    console.log('✓ Migration check complete');

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Run migrations if executed directly
if (require.main === module) {
  runMigrations();
}

module.exports = { runMigrations, extractVersion, loadEnvFile, parseDatabaseUrl, simulateConnection };

