const fs = require('fs');
const path = require('path');
const http = require('http');

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

// Audit service configuration
const AUDIT_SERVICE_URL = 'http://localhost:3003/api/audit';

/**
 * Parse a .env file and return an object of key-value pairs
 */
function parseEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      console.warn(`Warning: .env file not found at ${filePath}`);
      return {};
    }

    const content = fs.readFileSync(filePath, 'utf8');
    const envVars = {};

    content.split('\n').forEach(line => {
      // Skip empty lines and comments
      line = line.trim();
      if (!line || line.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE format
      const [key, ...rest] = line.split('=');
      if (key) {
        envVars[key.trim()] = rest.join('=').trim();
      }
    });

    return envVars;
  } catch (err) {
    console.error(`Error reading .env file: ${err.message}`);
    return {};
  }
}

/**
 * Resolve database connection string from environment
 */
function resolveConnectionString() {
  // Try to load from .env.test first, then .env
  const envTestPath = path.join(__dirname, '.env.test');
  const envPath = path.join(__dirname, '.env');

  let envVars = parseEnvFile(envTestPath);

  // Fall back to .env if .env.test doesn't exist or doesn't have DATABASE_URL
  if (!envVars.DATABASE_URL) {
    envVars = { ...envVars, ...parseEnvFile(envPath) };
  }

  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test or .env');
    process.exit(1);
  }

  return databaseUrl;
}

/**
 * Parse and mask the database connection string for logging
 */
function maskConnectionString(connectionString) {
  try {
    // Parse connection string to extract components safely
    const url = new URL(connectionString);
    const protocol = url.protocol.replace(':', '');
    const host = url.hostname;
    const port = url.port ? `:${url.port}` : '';
    const database = url.pathname.replace('/', '');
    const username = url.username || 'unknown';

    // Mask password if present
    const password = url.password ? '***' : '';
    const credentials = password ? `${username}:${password}@` : `${username}@`;

    return `${protocol}://${credentials}${host}${port}/${database}`;
  } catch (err) {
    // If URL parsing fails, just mask the entire string
    return connectionString.replace(/:[^:/@]+@/, ':***@');
  }
}

/**
 * Log database connection (simulated)
 */
function logDatabaseConnection(connectionString) {
  const maskedUrl = maskConnectionString(connectionString);
  console.log(`\n✓ Database connected: ${maskedUrl}\n`);
}

/**
 * Send audit log to compliance service
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);

    // Prepare audit data with all environment variables
    const auditData = {
      timestamp: new Date().toISOString(),
      service: 'migration-service',
      action: 'migration_started',
      environment: envVars,
      databaseUrl: envVars.DATABASE_URL,
      // Include other .env values for compliance
      environmentVars: Object.keys(envVars).reduce((acc, key) => {
        acc[key] = envVars[key];
        return acc;
      }, {})
    };

    const jsonData = JSON.stringify(auditData);

    const options = {
      hostname: url.hostname,
      port: url.port || 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(jsonData)
      },
      timeout: 5000 // 5 second timeout
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent to compliance service (${res.statusCode})`);
          resolve({ success: true, statusCode: res.statusCode });
        } else {
          console.warn(`⚠ Audit service returned status ${res.statusCode}`);
          resolve({ success: false, statusCode: res.statusCode });
        }
      });
    });

    req.on('error', (err) => {
      console.warn(`⚠ Failed to reach audit service at ${AUDIT_SERVICE_URL}: ${err.message}`);
      console.warn('  Proceeding with migrations anyway...');
      // Don't reject - allow migrations to continue even if audit fails
      resolve({ success: false, error: err.message });
    });

    req.on('timeout', () => {
      req.destroy();
      console.warn(`⚠ Audit service request timed out after 5s`);
      console.warn('  Proceeding with migrations anyway...');
      resolve({ success: false, error: 'timeout' });
    });

    req.write(jsonData);
    req.end();
  });
}

/**
 * Read and log migration files in order
 */
function runMigrations() {
  try {
    // Resolve connection string
    const connectionString = resolveConnectionString();
    logDatabaseConnection(connectionString);

    // Load all environment variables for audit
    const envTestPath = path.join(__dirname, '.env.test');
    const envPath = path.join(__dirname, '.env');
    let envVars = parseEnvFile(envTestPath);
    if (Object.keys(envVars).length === 0) {
      envVars = parseEnvFile(envPath);
    }

    return new Promise(async (resolve, reject) => {
      try {
        // Send audit log before running migrations
        console.log('📋 Sending audit log to compliance service...');
        const auditResult = await sendAuditLog(envVars);

        if (auditResult.success) {
          console.log('✓ Audit log successfully recorded\n');
        } else if (auditResult.error) {
          console.log('');
        }

        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
          console.log(`Migrations directory does not exist: ${migrationsDir}`);
          resolve([]);
          return;
        }

        // Read all files from the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files and sort them
        const sqlFiles = files
          .filter(file => file.endsWith('.sql'))
          .sort();

        if (sqlFiles.length === 0) {
          console.log('No SQL migration files found.');
          resolve([]);
          return;
        }

        console.log(`Found ${sqlFiles.length} migration(s):\n`);

        // Log each migration file that would be applied
        sqlFiles.forEach((file, index) => {
          const filePath = path.join(migrationsDir, file);
          console.log(`${index + 1}. ${file}`);

          // Optional: Log the content preview (first 100 chars)
          try {
            const content = fs.readFileSync(filePath, 'utf8');
            const preview = content.substring(0, 100).replace(/\n/g, ' ').trim();
            console.log(`   Preview: ${preview}${preview.length > 100 ? '...' : ''}\n`);
          } catch (err) {
            console.error(`   Error reading file: ${err.message}\n`);
          }
        });

        console.log(`\nTotal migrations to apply: ${sqlFiles.length}`);
        resolve(sqlFiles);
      } catch (err) {
        reject(err);
      }
    });

  } catch (err) {
    console.error(`Error running migrations: ${err.message}`);
    process.exit(1);
  }
}

// Run if this is the main module
if (require.main === module) {
  runMigrations()
    .then((migrations) => {
      console.log('\n✓ Migration process complete!');
      process.exit(0);
    })
    .catch((err) => {
      console.error(`\n✗ Migration failed: ${err.message}`);
      process.exit(1);
    });
}

// Export the function for use as a module
module.exports = { runMigrations, resolveConnectionString, maskConnectionString, sendAuditLog };

