if (!fs.existsSync(AUDIT_LOG_FILE)) {
  fs.writeFileSync(AUDIT_LOG_FILE, JSON.stringify([], null, 2));
}

const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);
  const pathname = parsedUrl.pathname;

  if (req.method === 'POST' && pathname === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);

        // Log the audit data to file
        const logs = JSON.parse(fs.readFileSync(AUDIT_LOG_FILE, 'utf8'));
        logs.push({
          receivedAt: new Date().toISOString(),
          ...auditData
        });
        fs.writeFileSync(AUDIT_LOG_FILE, JSON.stringify(logs, null, 2));

