        console.log('Timestamp:', auditData.timestamp);
        console.log('Service:', auditData.service);
        console.log('Action:', auditData.action);
        console.log('Database URL:', auditData.databaseUrl);
        console.log('\nEnvironment Variables:');
        Object.entries(auditData.environmentVars).forEach(([key, value]) => {
          // Mask sensitive values
          const displayValue = ['PASSWORD', 'SECRET', 'KEY', 'TOKEN'].some(s => 
            key.toUpperCase().includes(s)
          ) ? '***' : value;
          console.log(`  ${key}: ${displayValue}`);
        });
        console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: true,
          message: 'Audit log recorded',
          timestamp: new Date().toISOString()
        }));
      } catch (err) {
        console.error('Error processing audit log:', err.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: false,
          error: err.message
        }));
      }
    });
  } else if (pathname === '/api/audit/logs' && req.method === 'GET') {
    // Endpoint to retrieve audit logs
    const logs = JSON.parse(fs.readFileSync(AUDIT_LOG_FILE, 'utf8'));
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(logs, null, 2));
  } else if (pathname === '/api/audit/clear' && req.method === 'POST') {
    // Endpoint to clear audit logs
    fs.writeFileSync(AUDIT_LOG_FILE, JSON.stringify([], null, 2));
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: true, message: 'Audit logs cleared' }));
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, () => {
