  console.log(`\n  Audit logs stored in: ${AUDIT_LOG_FILE}\n`);
  console.log('Press Ctrl+C to stop the server\n');
});

server.on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error(`✗ Port ${PORT} is already in use. Please stop the other service.`);
  } else {
    console.error('Server error:', err.message);
  }
  process.exit(1);
});

