        console.log('\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
        console.log('📋 AUDIT LOG RECEIVED');
        console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
        console.log(`Timestamp: ${auditData.timestamp}`);
        console.log(`Service: ${auditData.service}`);
        console.log(`Environment: ${auditData.environment}`);
        console.log('\nEnvironment Variables:');
        Object.entries(auditData.variables).forEach(([key, value]) => {
          const maskedValue = key === 'DATABASE_URL' ? 
            value.replace(/:[^:/@]+@/, ':****@') : value;
          console.log(`  ${key}: ${maskedValue}`);
        });
        console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, message: 'Audit logged' }));
      } catch (error) {
        console.error('Error parsing audit data:', error);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.on('request', (req, res) => {
  req.path = new URL(req.url, `http://${req.headers.host}`).pathname;
});

server.listen(PORT, 'localhost', () => {
  console.log(`🔍 Mock Audit Service listening on http://localhost:${PORT}`);
  console.log('Press Ctrl+C to stop\n');
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\nShutting down audit service...');
  server.close();
  process.exit(0);
});

