#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:3004/api/audit';

/**
 * Loads environment variables from .env.test file and returns them as an object
 */
function loadEnvFile(filePath) {
  const envVars = {};

  try {
    if (!fs.existsSync(filePath)) {
      throw new Error(`Environment file not found: ${filePath}`);
    }

    const envContent = fs.readFileSync(filePath, 'utf8');
    const lines = envContent.split('\n');

    lines.forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim();

      // Remove quotes if present
      const cleanValue = value.replace(/^["']|["']$/g, '');

      const trimmedKey = key.trim();
      envVars[trimmedKey] = cleanValue;
      process.env[trimmedKey] = cleanValue;
    });
  } catch (error) {
    throw new Error(`Failed to load environment file: ${error.message}`);
  }

  return envVars;
}

// Load environment variables
const envVars = loadEnvFile(ENV_FILE);

/**
 * Resolves the database connection string from environment variables
 */
function resolveConnectionString() {
  const connectionString = process.env.DATABASE_URL;

  if (!connectionString) {
    throw new Error(
      'DATABASE_URL not found in environment. ' +
      'Please ensure .env.test file exists with DATABASE_URL defined.'
    );
  }

  return connectionString;
}

/**
 * Simulates connecting to the database and logs success
 */
function connectToDatabase(connectionString) {
  console.log('Connecting to database...');
  console.log(`Connection string: ${connectionString}`);

  // Simulate connection success
  console.log('✓ Successfully connected to database');
  console.log();
}

/**
 * Sends connection details to the migration audit service for compliance logging
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    try {
      const auditData = {
        timestamp: new Date().toISOString(),
        environment: 'test',
        connectionDetails: envVars
      };

      const jsonPayload = JSON.stringify(auditData);

      console.log('Sending audit log to compliance service...');
      console.log(`POST ${AUDIT_SERVICE_URL}`);

      const urlParts = new URL(AUDIT_SERVICE_URL);
      const options = {
        hostname: urlParts.hostname,
        port: urlParts.port,
        path: urlParts.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(jsonPayload)
        }
      };

      const req = http.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✓ Audit log sent successfully (HTTP ${res.statusCode})`);
            console.log();
            resolve();
          } else {
            reject(new Error(
              `Audit service returned status ${res.statusCode}: ${responseData}`
            ));
          }
        });
      });

      req.on('error', (error) => {
        reject(new Error(
          `Failed to connect to audit service at ${AUDIT_SERVICE_URL}: ${error.message}`
        ));
      });

      // Set a timeout for the request
      req.setTimeout(5000, () => {
        req.destroy();
        reject(new Error(
          `Audit service request timed out after 5 seconds`
        ));
      });

      req.write(jsonPayload);
      req.end();
    } catch (error) {
      reject(new Error(`Error preparing audit log: ${error.message}`));
    }
  });
}

/**
 * Reads SQL migration files from the migrations directory
 * and logs each filename in order
 */
async function runMigrations() {
  try {
    // Resolve and connect to database
    const connectionString = resolveConnectionString();
    connectToDatabase(connectionString);

    // Send audit log to compliance service
    await sendAuditLog(envVars);

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory does not exist: ${MIGRATIONS_DIR}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log('Migrations directory created.');
      return;
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file) === '.sql')
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    sqlFiles.forEach((file, index) => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      console.log(`[${index + 1}] ${file}`);
    });

    console.log('\n--- Migration Summary ---');
    console.log(`Total migrations to apply: ${sqlFiles.length}`);
