    }
    console.log('\nAll migrations applied successfully!');
    */

  } catch (error) {
    console.error('Error running migrations:', error.message);
    process.exit(1);
  }
}

// Run migrations if script is executed directly
if (require.main === module) {
  runMigrations();
}

