const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads and processes SQL migration files
 * from the ./migrations/ directory in lexicographic order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Read all migration files from the migrations directory and return them sorted
 * @returns {Promise<string[]>} Array of migration filenames in order
 */
async function getMigrationFiles() {
  try {
    const files = await fs.promises.readdir(MIGRATIONS_DIR);

    // Filter for .sql files and sort them in lexicographic order
    const migrationFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return migrationFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      process.exit(1);
    }
    throw error;
  }
}

/**
 * Read content of a migration file
 * @param {string} filename - The migration filename
 * @returns {Promise<string>} The file content
 */
async function readMigrationFile(filename) {
  const filePath = path.join(MIGRATIONS_DIR, filename);
  return fs.promises.readFile(filePath, 'utf-8');
}

/**
 * Apply migrations - logs each migration that would be applied
 */
async function migrate() {
  console.log(`\n📋 Database Migration Script`);
  console.log(`📁 Reading from: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = await getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('ℹ️  No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  for (const filename of migrationFiles) {
    console.log(`  ✓ ${filename}`);

    try {
