const http = require('http');

/**
 * Simple mock audit service for testing migration compliance logging
 */

const PORT = 3003;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.path === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('\n📨 Audit Service - Received migration audit log:');
        console.log('─'.repeat(50));
        console.log(JSON.stringify(auditData, null, 2));
        console.log('─'.repeat(50));

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          success: true, 
          message: 'Audit logged successfully',
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

// Fix for older Node versions - add pathname parsing
const originalOn = server.on.bind(server);
server.on = function(event, callback) {
  if (event === 'request') {
    return originalOn(event, (req, res) => {
      const url = require('url');
      const parsedUrl = url.parse(req.url);
      req.path = parsedUrl.pathname;
      callback(req, res);
    });
  }
  return originalOn(event, callback);
};

// Handle inline request parsing
const oldCreateServer = http.createServer;
http.createServer = function(listener) {
  const srv = oldCreateServer((req, res) => {
    const url = require('url');
    const parsedUrl = url.parse(req.url);
    req.path = parsedUrl.pathname;
    listener(req, res);
  });
  return srv;
};

server.listen(PORT, () => {
  console.log(`\n🚀 Audit Service running on http://localhost:${PORT}`);
  console.log(`   Listening for POST requests at /api/audit\n`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('\n⏹️  Audit service shutting down...');
  server.close();
  process.exit(0);
});

