#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

async function runMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      console.log('Migrations directory created.');
      return;
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log(`Found ${sqlFiles.length} migration(s):\n`);

    // Log each migration file in order
    sqlFiles.forEach((file, index) => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      const stats = fs.statSync(filePath);
      console.log(`  ${index + 1}. ${file} (${stats.size} bytes)`);
    });

    console.log('\nMigrations would be applied in the order shown above.');

    // Optional: Show which migrations would be executed
    console.log('\n--- Migration Execution Order ---');
    sqlFiles.forEach((file, index) => {
      console.log(`Step ${index + 1}: Executing ${file}`);
    });

  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

// Run migrations if this script is executed directly
if (require.main === module) {
  runMigrations().catch(error => {
    console.error('Migration error:', error);
    process.exit(1);
  });
}

module.exports = { runMigrations };

