const path = require('path');
const http = require('http');
const https = require('https');

// Try to load dotenv, use fallback if not installed
let dotenv;
try {
  dotenv = require('dotenv');
} catch (error) {
  // Fallback: simple dotenv parser if dotenv module is not installed
  dotenv = {
    parse: (envString) => {
      const config = {};
      envString.toString().split('\n').forEach(line => {
        const [key, ...rest] = line.split('=');
        if (key && !key.startsWith('#')) {
          config[key.trim()] = rest.join('=').trim();
        }
      });
      return config;
    }
  };
}

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:3003/api/audit';

function resolveConnection(envConfig) {
  if (!envConfig || !envConfig.DATABASE_URL) {
    console.warn('Warning: DATABASE_URL not found in .env.test');
    return null;
  }

  return envConfig.DATABASE_URL;
}

function sendAuditLog(envConfig) {
  return new Promise((resolve, reject) => {
    try {
      const auditData = {
        timestamp: new Date().toISOString(),
        action: 'migration_start',
        environment: envConfig || {},
        hostname: require('os').hostname(),
        user: process.env.USER || 'unknown'
      };

      const payload = JSON.stringify(auditData);

      const urlObj = new URL(AUDIT_SERVICE_URL);
      const options = {
        hostname: urlObj.hostname,
        port: urlObj.port || 80,
        path: urlObj.pathname + urlObj.search,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(payload)
        },
        timeout: 5000
      };

      const client = urlObj.protocol === 'https:' ? https : http;

      console.log(`\nSending audit log to ${AUDIT_SERVICE_URL}...`);

      const req = client.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✓ Audit log sent successfully (${res.statusCode})\n`);
            resolve();
          } else {
            console.warn(`⚠ Audit service returned status ${res.statusCode}\n`);
            resolve(); // Don't fail migration on audit errors
          }
        });
      });

      req.on('error', (error) => {
        console.warn(`⚠ Failed to send audit log: ${error.message}`);
        console.warn('Continuing with migration...\n');
        resolve(); // Don't fail migration on audit errors
      });

      req.on('timeout', () => {
        req.destroy();
        console.warn('⚠ Audit service request timed out');
        console.warn('Continuing with migration...\n');
        resolve(); // Don't fail migration on audit errors
      });

      req.write(payload);
      req.end();
    } catch (error) {
      console.warn(`⚠ Error preparing audit log: ${error.message}`);
      console.warn('Continuing with migration...\n');
      resolve(); // Don't fail migration on audit errors
