const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and return key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const env = {};

    content.split('\n').forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) return;

      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim();

      if (key && value) {
        // Remove surrounding quotes if present
        env[key.trim()] = value.replace(/^['"]|['"]$/g, '');
      }
    });

    return env;
  } catch (error) {
    if (error.code === 'ENOENT') {
      throw new Error(`.env.test file not found at ${filePath}`);
    }
    throw error;
  }
}

/**
 * Load DATABASE_URL from .env.test
 * @returns {string} The DATABASE_URL value
 */
function loadDatabaseUrl() {
  const env = parseEnvFile(ENV_FILE);

