const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:3003/api/audit';

/**
 * Parses the .env.test file and returns an object of all environment variables
 */
function parseEnvFile() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      throw new Error(`Environment file not found at ${ENV_FILE}`);
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      const match = trimmedLine.match(/^\s*([^=]+)\s*=\s*(.+?)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();
        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error parsing environment file: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Sends audit log to the migration audit service
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit log sent to migration service (HTTP ${res.statusCode})`);
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to connect to audit service: ${error.message}`));
    });

    req.write(payload);
    req.end();
  });
}

/**
 * Reads migration files from the ./migrations/ directory and logs them in order
 */
