const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 * in the order they would be applied
 * Connects to database using DATABASE_URL from .env.test
 */

const migrationsDir = path.join(__dirname, 'migrations');
const envTestFile = path.join(__dirname, '.env.test');

/**
 * Load all environment variables from .env.test file
 */
function loadEnvVariables() {
  try {
    if (!fs.existsSync(envTestFile)) {
      throw new Error(`.env.test file not found at ${envTestFile}`);
    }

    // Read the .env.test file
    const envContent = fs.readFileSync(envTestFile, 'utf8');

    // Parse all key=value pairs
    const envVars = {};
    const lines = envContent.split('\n');

    lines.forEach(line => {
      line = line.trim();
      // Skip empty lines and comments
      if (!line || line.startsWith('#')) {
        return;
      }

      const match = line.match(/^\s*([^=]+?)\s*=\s*(.+)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();
        // Remove quotes if present
        value = value.replace(/^["']|["']$/g, '');
        envVars[key] = value;
      }
    });

    if (!envVars.DATABASE_URL) {
      throw new Error('DATABASE_URL not found in .env.test');
    }

    return envVars;
  } catch (error) {
    console.error('Error loading environment variables:', error.message);
    process.exit(1);
  }
}

/**
 * Send audit log to compliance service
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const auditData = {
      timestamp: new Date().toISOString(),
      action: 'database_migration_started',
      environment: 'test',
      ...envVars
    };

    const jsonData = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 3003,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(jsonData)
      }
    };

    console.log('Sending compliance audit log...\n');

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✓ Audit logged successfully (HTTP ${res.statusCode})`);
          console.log(`  Service: http://localhost:3003/api/audit`);
          console.log(`  Timestamp: ${auditData.timestamp}\n`);
          resolve(true);
        } else {
          console.error(`✗ Audit logging failed (HTTP ${res.statusCode})`);
          console.error(`  Response: ${responseData}\n`);
          reject(new Error(`Audit service returned ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error(`✗ Failed to connect to audit service: ${error.message}`);
      console.error(`  Make sure http://localhost:3003/api/audit is running\n`);
      reject(error);
    });

    // Send the request
    req.write(jsonData);
    req.end();
  });
}

/**
 * Connect to database (simulated - just logs the connection)
 */
function connectToDatabase(databaseUrl) {
  try {
    // Parse the connection string to extract database name
    const urlObj = new URL(databaseUrl);
    const dbName = urlObj.pathname.replace(/^\//g, '') || 'unknown';
    const host = urlObj.hostname;
    const protocol = urlObj.protocol.replace(':', '');

    console.log(`✓ Connected to database: ${dbName}`);
    console.log(`  Protocol: ${protocol}`);
    console.log(`  Host: ${host}`);
    console.log(`  Connection string: ${databaseUrl}\n`);

    return true;
  } catch (error) {
    console.error('Error parsing database URL:', error.message);
    process.exit(1);
  }
}

/**
 * Read and sort migration files
 * Assumes files are named with a numeric prefix (e.g., 001_init.sql, 002_add_users.sql)
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory not found: ${migrationsDir}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(migrationsDir, { recursive: true });
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => path.extname(file).toLowerCase() === '.sql');

    // Sort files alphabetically (which preserves numeric prefix order if named correctly)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Main migration function
 * Logs each migration file that would be applied
 */
function migrate() {
  console.log('Starting database migration...\n');
  console.log(`Migrations directory: ${migrationsDir}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(migrationsDir, file);
    const fileSize = fs.statSync(filePath).size;
    console.log(`${index + 1}. ${file} (${fileSize} bytes)`);
  });

  console.log('\nMigration files would be applied in the order listed above.');
}

/**
 * Main application entry point
 */
async function main() {
  console.log('Database Migration Script\n');
  console.log('=' . repeat(50));
  console.log('Loading configuration...\n');

  // Load all environment variables from .env.test
  const envVars = loadEnvVariables();

  // Connect to database
  connectToDatabase(envVars.DATABASE_URL);

  // Send audit log to compliance service before running migrations
  try {
    await sendAuditLog(envVars);
  } catch (error) {
    console.error('Aborting migration: Audit logging failed');
    process.exit(1);
  }

  // Run migrations
  migrate();

