#!/usr/bin/env node

const http = require('http');

const PORT = 3003;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.path === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('\n📋 Audit Log Received:');
        console.log(JSON.stringify(auditData, null, 2));
        console.log('\n');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          success: true, 
          message: 'Audit logged successfully',
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, '127.0.0.1', () => {
  console.log(`🚀 Mock Audit Service running on http://localhost:${PORT}`);
  console.log('Waiting for audit requests...\n');
});

// Handle shutdown gracefully
process.on('SIGINT', () => {
  console.log('\n\n🛑 Audit service shutting down...');
  server.close();
  process.exit(0);
});

