#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 * Migrations are applied in lexicographic order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Read and sort migration files
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('🔄 Database Migration Script');
  console.log('============================\n');

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('ℹ️  No SQL migration files found in ./migrations/ directory');
    return;
  }

  console.log(`📁 Found ${migrations.length} migration(s):\n`);

  migrations.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const fileSize = fs.statSync(filePath).size;
    console.log(`  ${index + 1}. ${filename} (${fileSize} bytes)`);
  });

  console.log('\n✅ Migration plan complete');
  console.log('');
  console.log('To apply these migrations, implement database connection logic');
  console.log('and execute each SQL file in the order shown above.');
}

// Run migrations
runMigrations();

