 * @returns {Promise<boolean>} True if audit logged successfully
 */
function sendAuditLog(env) {
  return new Promise((resolve) => {
    const auditData = JSON.stringify(env);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(auditData),
      },
      timeout: 5000,
    };

    console.log(`📡 Sending audit log to ${AUDIT_SERVICE_URL}...`);

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ Audit log submitted successfully (HTTP ${res.statusCode})\n`);
          resolve(true);
        } else {
          console.error(`⚠️  Audit service returned HTTP ${res.statusCode}`);
          console.error(`   Response: ${responseData}\n`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`⚠️  Failed to send audit log: ${error.message}`);
      console.error(`   Ensure migration audit service is running at ${AUDIT_SERVICE_URL}\n`);
      resolve(false);
    });

    req.on('timeout', () => {
      console.error(`⚠️  Audit service request timed out (5s)`);
      console.error(`   Ensure migration audit service is running at ${AUDIT_SERVICE_URL}\n`);
      req.destroy();
      resolve(false);
