#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename
 * Migrations are applied in lexicographic order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:3003/api/audit';

/**
 * Send audit log to compliance service
 * @param {object} env Environment variables to log
 * @returns {Promise<boolean>} True if audit logged successfully
 */
function sendAuditLog(env) {
  return new Promise((resolve) => {
    const auditData = JSON.stringify(env);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(auditData),
      },
      timeout: 5000,
    };

    console.log(`📡 Sending audit log to ${AUDIT_SERVICE_URL}...`);

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ Audit log submitted successfully (HTTP ${res.statusCode})\n`);
          resolve(true);
        } else {
          console.error(`⚠️  Audit service returned HTTP ${res.statusCode}`);
          console.error(`   Response: ${responseData}\n`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`⚠️  Failed to send audit log: ${error.message}`);
      console.error(`   Ensure migration audit service is running at ${AUDIT_SERVICE_URL}\n`);
      resolve(false);
    });

    req.on('timeout', () => {
      console.error(`⚠️  Audit service request timed out (5s)`);
      console.error(`   Ensure migration audit service is running at ${AUDIT_SERVICE_URL}\n`);
      req.destroy();
      resolve(false);
    });

    req.write(auditData);
    req.end();
  });
}

/**
 * Load environment variables from .env.test
 * @returns {object} Parsed environment variables
 */
function loadEnvironment() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.error(`Error: Environment file not found at ${ENV_FILE}`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const env = {};

    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (!line.trim() || line.trim().startsWith('#')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim();

      if (key && key.trim()) {
        env[key.trim()] = value;
      }
    });

    return env;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Resolve database connection string
 * @param {object} env Environment variables
 * @returns {string} DATABASE_URL or null if not found
 */
function getDatabaseUrl(env) {
  return env.DATABASE_URL || null;
}

/**
 * Simulate database connection
 * @param {string} databaseUrl Connection string
 * @returns {boolean} True if connection successful
 */
function connectDatabase(databaseUrl) {
  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    return false;
  }

  // Log the connection attempt (simulated)
  console.log(`✅ Connected successfully to database`);
  console.log(`   Connection string: ${databaseUrl}\n`);
  return true;
}

/**
 * Read and sort migration files
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory not found at ${MIGRATIONS_DIR}`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('🔄 Database Migration Script');
  console.log('============================\n');

  // Load environment variables
  console.log('📋 Loading environment from .env.test...');
