  console.log('🔗 Resolving database connection...');
  const databaseUrl = getDatabaseUrl(env);

  if (!connectDatabase(databaseUrl)) {
    process.exit(1);
  }

  // Send audit log before running migrations
  sendAuditLog(env).then((auditSuccess) => {
    if (!auditSuccess) {
      console.warn('⚠️  Warning: Audit log submission failed, but continuing with migrations...\n');
    }

    // Get migrations
    const migrations = getMigrationFiles();

    if (migrations.length === 0) {
      console.log('ℹ️  No SQL migration files found in ./migrations/ directory');
      return;
    }

    console.log(`📁 Found ${migrations.length} migration(s):\n`);

    migrations.forEach((filename, index) => {
